-- Verified reviews of published solutions (docs/reviews.md). Additive; existing solutions
-- start with none: no seeded or imported reviews.
--
-- One review per account and solution. The founder answers in public but can never
-- delete a review (the rule §46 set for comments); only ops hides one, with a reason.
-- A review is public only while its author's email is verified — that is checked when
-- reading, so verifying later publishes it without touching this row.
CREATE TABLE IF NOT EXISTS solution_reviews (
  -- Generated by the client: a retried submit returns the same row instead of a second one.
  id uuid PRIMARY KEY,
  solution_id uuid NOT NULL REFERENCES founder_solutions(id) ON DELETE CASCADE,
  author_id uuid NOT NULL REFERENCES auth_accounts(id) ON DELETE CASCADE,
  author_name varchar(60) NOT NULL CHECK (char_length(btrim(author_name)) > 0),
  rating smallint NOT NULL CHECK (rating BETWEEN 1 AND 5),
  recommends boolean NOT NULL,
  headline varchar(120) NOT NULL CHECK (char_length(btrim(headline)) >= 5),
  use_case varchar(600) NOT NULL CHECK (char_length(btrim(use_case)) >= 20),
  pros varchar(1500) NOT NULL CHECK (char_length(btrim(pros)) >= 20),
  cons varchar(1500) NOT NULL CHECK (char_length(btrim(cons)) >= 20),
  usage_duration text NOT NULL
    CHECK (usage_duration IN ('trial', 'lt6m', '6to12m', '1to2y', 'gt2y')),
  company_size text CHECK (company_size IN ('micro', 'pyme', 'mediana', 'corporativo')),
  country char(2) CHECK (country ~ '^[A-Z]{2}$'),
  status text NOT NULL DEFAULT 'published' CHECK (status IN ('published', 'hidden')),
  hidden_reason varchar(500),
  reply varchar(1500) CHECK (reply IS NULL OR char_length(btrim(reply)) > 0),
  reply_at timestamptz,
  version integer NOT NULL DEFAULT 1,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (solution_id, author_id),
  CHECK ((status = 'hidden') = (hidden_reason IS NOT NULL)),
  CHECK ((reply IS NULL) = (reply_at IS NULL))
);
CREATE INDEX IF NOT EXISTS solution_reviews_solution
  ON solution_reviews (solution_id, created_at DESC, id);
CREATE INDEX IF NOT EXISTS solution_reviews_author
  ON solution_reviews (author_id, created_at DESC);

-- Reports on a review, mirroring community_reports (§56). review_id is SET NULL, not
-- CASCADE: deleting the review must not erase the record of how its report was decided.
CREATE TABLE IF NOT EXISTS solution_review_reports (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  review_id uuid REFERENCES solution_reviews(id) ON DELETE SET NULL,
  solution_id uuid NOT NULL REFERENCES founder_solutions(id) ON DELETE CASCADE,
  reporter_id uuid REFERENCES auth_accounts(id) ON DELETE SET NULL,
  reason text NOT NULL CHECK (reason IN ('fake', 'conflict', 'abuse', 'spam', 'other')),
  details varchar(2000) NOT NULL CHECK (char_length(btrim(details)) >= 10),
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'resolved', 'dismissed')),
  decision varchar(2000),
  reviewer_id uuid REFERENCES auth_accounts(id) ON DELETE SET NULL,
  resolved_at timestamptz,
  version integer NOT NULL DEFAULT 1,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
-- One open report per person and review; a retry answers 409 instead of piling up.
CREATE UNIQUE INDEX IF NOT EXISTS solution_review_reports_open
  ON solution_review_reports (review_id, reporter_id) WHERE status = 'open';
CREATE INDEX IF NOT EXISTS solution_review_reports_status
  ON solution_review_reports (status, created_at DESC);

-- The founder hears about a review once it is public: written by a verified account, or
-- later, when its author confirms their email. Both paths share the source key, so one
-- review notifies once. Category 'solution' follows the founder's existing email
-- preference for their listings. The title stays in Spanish like the other triggers (§63).
CREATE OR REPLACE FUNCTION notify_solution_review(review uuid) RETURNS void LANGUAGE plpgsql AS $$
DECLARE target uuid; solution uuid; enabled boolean;
BEGIN
  SELECT s.owner_id, s.id INTO target, solution
    FROM solution_reviews r
    JOIN founder_solutions s ON s.id = r.solution_id
    JOIN auth_accounts a ON a.id = r.author_id
   WHERE r.id = review AND r.status = 'published' AND a.email_verified_at IS NOT NULL
     AND r.author_id <> s.owner_id;
  IF target IS NULL THEN RETURN; END IF;
  SELECT p.solution_email AND a.email_verified_at IS NOT NULL INTO enabled
    FROM auth_accounts a LEFT JOIN notification_preferences p ON p.owner_id = a.id
   WHERE a.id = target;
  INSERT INTO account_notifications (owner_id, category, source_key, title, href, email_state)
  VALUES (target, 'solution', 'review:' || review, 'Nueva reseña de tu solución',
    '/account/solutions/' || solution, CASE WHEN enabled THEN 'pending' ELSE 'disabled' END)
  ON CONFLICT (source_key) DO NOTHING;
END $$;

CREATE OR REPLACE FUNCTION notify_solution_review_insert() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  PERFORM notify_solution_review(NEW.id);
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS solution_review_notification ON solution_reviews;
CREATE TRIGGER solution_review_notification AFTER INSERT ON solution_reviews
  FOR EACH ROW EXECUTE FUNCTION notify_solution_review_insert();

CREATE OR REPLACE FUNCTION notify_reviews_on_verification() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE review uuid;
BEGIN
  FOR review IN SELECT id FROM solution_reviews WHERE author_id = NEW.id LOOP
    PERFORM notify_solution_review(review);
  END LOOP;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS solution_review_author_verified ON auth_accounts;
CREATE TRIGGER solution_review_author_verified AFTER UPDATE OF email_verified_at ON auth_accounts
  FOR EACH ROW WHEN (OLD.email_verified_at IS NULL AND NEW.email_verified_at IS NOT NULL)
  EXECUTE FUNCTION notify_reviews_on_verification();
